33	export function findMarkdownFiles(contentDir: string): string[] {
34	  if (!fs.existsSync(contentDir)) {
35	    throw new Error(`Content directory not found: ${contentDir}`);
36	  }
37	  return fs
38	    .readdirSync(contentDir)
39	    .filter((file) => file.toLowerCase().endsWith('.md'))
40	    .sort();
41	}
