59	export function build(options: BuildOptions): BuildResult {
60	  const { contentDir, outputDir, templatesDir = defaultTemplatesDir() } = options;
61	  const files = findMarkdownFiles(contentDir);
62	  const pages = files.map((file) => buildPage(contentDir, file, templatesDir));
63	
64	  fs.mkdirSync(outputDir, { recursive: true });
65	  for (const page of pages) {
66	    fs.writeFileSync(path.join(outputDir, page.outputPath), page.html, 'utf-8');
67	  }
68	  const engine = getTemplateEngine(templatesDir);
69	  fs.writeFileSync(path.join(outputDir, 'index.html'), engine.renderIndex(pages), 'utf-8');
70	
71	  return { pages, outputDir };
72	}
