15	const FALLBACK_LAYOUT = `<!DOCTYPE html>
16	<html lang="en">
17	<head>
18	<meta charset="UTF-8">
19	<title>{{title}}</title>
20	</head>
21	<body>
22	<article>
23	<h1>{{title}}</h1>
24	{{#if date}}<p class="date">{{date}}</p>
25	{{/if}}{{#if tags.length}}<ul class="tags">{{#each tags}}<li>{{this}}</li>{{/each}}</ul>
26	{{/if}}{{{body}}}
27	</article>
28	</body>
29	</html>
30	`;
31	
32	const FALLBACK_INDEX = `<!DOCTYPE html>
33	<html lang="en">
34	<head>
35	<meta charset="UTF-8">
36	<title>Index</title>
37	</head>
38	<body>
39	<h1>All Pages</h1>
40	<ul class="page-list">
41	{{#each pages}}
42	<li><a href="{{outputPath}}">{{title}}</a>{{#if date}} <span class="date">{{date}}</span>{{/if}}</li>
43	{{/each}}
44	</ul>
45	</body>
46	</html>
