49	/**
50	 * Compiles page and index templates for a single ./templates directory.
51	 * Falls back to built-in Handlebars templates when the project has no
52	 * templates directory (or is missing the default layout/index template),
53	 * so `ssg build` keeps working without any project scaffolding.
54	 */
55	export class TemplateEngine {
56	  private readonly layoutsDir: string;
57	  private readonly partialsDir: string;
58	  private readonly indexTemplatePath: string;
59	  private readonly handlebars: typeof Handlebars;
60	  private readonly layoutCache = new Map<string, HandlebarsTemplateDelegate>();
61	  private indexTemplate?: HandlebarsTemplateDelegate;
62	  private partialsRegistered = false;
63	
64	  constructor(templatesDir: string) {
65	    this.layoutsDir = path.join(templatesDir, 'layouts');
66	    this.partialsDir = path.join(templatesDir, 'partials');
67	    this.indexTemplatePath = path.join(templatesDir, 'index.hbs');
68	    this.handlebars = Handlebars.create();
69	  }
70	
71	  private registerPartials(): void {
72	    if (this.partialsRegistered) return;
73	    this.partialsRegistered = true;
74	    if (!fs.existsSync(this.partialsDir)) return;
75	    for (const file of fs.readdirSync(this.partialsDir)) {
76	      if (!file.toLowerCase().endsWith('.hbs')) continue;
77	      const name = file.replace(/\.hbs$/i, '');
78	      const source = fs.readFileSync(path.join(this.partialsDir, file), 'utf-8');
79	      this.handlebars.registerPartial(name, source);
80	    }
81	  }
82	
83	  private loadLayout(name: string): HandlebarsTemplateDelegate {
84	    this.registerPartials();
85	    const cached = this.layoutCache.get(name);
86	    if (cached) return cached;
87	
88	    const layoutPath = path.join(this.layoutsDir, `${name}.hbs`);
89	    let source: string;
90	    if (fs.existsSync(layoutPath)) {
91	      source = fs.readFileSync(layoutPath, 'utf-8');
92	    } else if (name === DEFAULT_LAYOUT_NAME) {
93	      source = FALLBACK_LAYOUT;
94	    } else {
95	      throw new Error(`Unknown template "${name}": no layout found at ${layoutPath}`);
96	    }
97	
98	    const compiled = this.handlebars.compile(source);
99	    this.layoutCache.set(name, compiled);
100	    return compiled;
101	  }
102	
103	  renderPage(data: PageTemplateData, templateName?: string): string {
104	    const name = templateName && templateName.trim().length > 0 ? templateName.trim() : DEFAULT_LAYOUT_NAME;
105	    const layout = this.loadLayout(name);
106	    return layout({
107	      title: data.title,
108	      date: data.date,
109	      tags: data.tags,
110	      body: data.body,
111	    });
112	  }
113	
114	  renderIndex(pages: Page[]): string {
115	    this.registerPartials();
116	    if (!this.indexTemplate) {
117	      const source = fs.existsSync(this.indexTemplatePath)
118	        ? fs.readFileSync(this.indexTemplatePath, 'utf-8')
119	        : FALLBACK_INDEX;
120	      this.indexTemplate = this.handlebars.compile(source);
121	    }
122	    return this.indexTemplate({ pages });
123	  }
124	}
125	
126	const engineCache = new Map<string, TemplateEngine>();
127	
128	export function getTemplateEngine(templatesDir: string): TemplateEngine {
129	  let engine = engineCache.get(templatesDir);
130	  if (!engine) {
131	    engine = new TemplateEngine(templatesDir);
132	    engineCache.set(templatesDir, engine);
133	  }
134	  return engine;
135	}
